mapper.select:
select

from asset
where id = #{assetId}
  and kb_id = #{kbId}
  and deleted_at is null

select

from asset
where kb_id = #{kbId}
  and deleted_at is null
order by created_at desc, id desc
limit #{limit} offset #{offset}

select coalesce(max(version_no), 0)
from asset
where kb_id = #{kbId}
  and version_group_id = #{versionGroupId}

mapper.update:
update asset
set parse_status = #{parseStatus},
    index_status = #{indexStatus},
    error_code = null,
    error_message = null,
    updated_by = #{updatedBy},
    updated_at = #{updatedAt}
where id = #{assetId}
  and kb_id = #{kbId}
  and deleted_at is null

update asset
set updated_by = #{updatedBy},
    updated_at = #{updatedAt},
    deleted_at = #{updatedAt}
where id = #{assetId}
  and kb_id = #{kbId}
  and deleted_at is null
